{ config, pkgs, inputs, lib, ... }: let
  flakeInputs = lib.filterAttrs (_: lib.isType "flake") inputs;
  bespoke-zellij = inputs.dim-unfocused.packages.x86_64-linux;
  zellij-main = bespoke-zellij.zellij;
  dim-unfocused-wasm = bespoke-zellij.dim-unfocused;
  llm-agents = inputs.llm-agents.packages.x86_64-linux;
  mdv = inputs.mdv.packages.${pkgs.stdenv.hostPlatform.system}.default;
  merman = inputs.merman.packages.${pkgs.stdenv.hostPlatform.system}.default;
  mcp = import ./mcp.nix { inherit pkgs lib; };
  agentDirenv = import ./agent-direnv.nix { inherit pkgs; };
  codex-cfg = import ./codex.nix { inherit lib; };
  grok-cfg = import ./grok.nix { inherit lib grok; inherit (mcp) servers; };
  docTools = import ./doc-tools.nix { inherit pkgs; };
  claude = pkgs.writeShellApplication {
    name = "claude";
    runtimeInputs = [ llm-agents.claude-code ] ++ docTools.tools;
    # `=` form is required: --mcp-config is variadic and would otherwise consume
    # subsequent positional args as additional config files.
    #
    # `--effort xhigh` rather than CLAUDE_CODE_EFFORT_LEVEL=xhigh: the env var
    # is consulted ahead of everything else and pins the session, so /effort
    # just refuses ("Not applied: CLAUDE_CODE_EFFORT_LEVEL=xhigh overrides
    # effort this session"). The flag only seeds the session's starting level,
    # leaving /effort free to change it. The `effortLevel` setting is not an
    # option either: /effort saves its pick there, so later sessions would start
    # at whatever level was picked last instead of xhigh.
    # Placed before "$@" because the last --effort wins, so an explicit
    # `claude --effort high` still overrides this default.
    text = ''
      # Load each project's direnv environment before every Bash command.
      export CLAUDE_ENV_FILE=${agentDirenv.loader}
      exec claude --mcp-config=${mcp.claudeMcpConfig} --effort xhigh "$@"
    '';
  };
  codex = pkgs.writeShellApplication {
    name = "codex";
    # agentDirenv.bash first: Codex runs commands with the first bash on PATH.
    runtimeInputs = [ agentDirenv.bash llm-agents.codex ] ++ docTools.tools;
    text = ''exec codex ${lib.concatStringsSep " " (mcp.codexArgs ++ codex-cfg.configArgs)} "$@"'';
  };
  agy = llm-agents.antigravity-cli;
  grok = llm-agents.grok;
  # nixpkgs.linear is the macOS desktop app; llm-agents does not package the
  # CLI yet. Pin the upstream Linux binary until it has a maintained Nix package.
  linear-cli = pkgs.stdenvNoCC.mkDerivation (finalAttrs: {
    pname = "linear-cli";
    version = "3.1.0";
    src = pkgs.fetchurl {
      url = "https://github.com/schpet/linear-cli/releases/download/v${finalAttrs.version}/linear-x86_64-unknown-linux-gnu.tar.xz";
      hash = "sha256-v3cSCXzmoB6KN53oNX7KZtV0gFAgHTNrp4e2rTaH8+c=";
    };
    nativeBuildInputs = [ pkgs.autoPatchelfHook pkgs.makeWrapper pkgs.installShellFiles ];
    buildInputs = [ pkgs.stdenv.cc.cc.lib ];
    dontBuild = true;
    installPhase = ''
      runHook preInstall
      install -Dm755 linear "$out/bin/linear"
      install -Dm644 LICENSE "$out/share/licenses/linear-cli/LICENSE"
      install -Dm644 THIRD_PARTY_LICENSES.md "$out/share/licenses/linear-cli/THIRD_PARTY_LICENSES.md"
      runHook postInstall

